            INSERT INTO {{ ref_no_link(node.location.name, node.name) }}
            (
                {% for col in source.columns %}
                    `{{ col.name | escape_identifier }}`
                    {%- if not loop.last -%},{% endif %}
                {% endfor %}
            )
        {% endif %}

        {{ source.cteString }}
        SELECT{% if source.selectModifier %} {{ source.selectModifier }}{% endif %}
        {% for col in source.columns %}
            {{ get_source_transform(col) }} AS `{{ col.name | escape_identifier }}`
            {%- if not loop.last -%}, {% endif %}
        {% endfor %}

        {{ source.join }}

        {% if config.insertStrategy in ['UNION', 'UNION ALL'] and not loop.last %}
            {{ 'UNION DISTINCT' if config.insertStrategy == 'UNION' else config.insertStrategy }}
        {% endif %}
    {% endfor %}

    {% if config.postSQL %}
        {{ stage('Post-SQL') }}
        {{ config.postSQL }}
    {% endif %}
{% endif %}

{% if config.testsEnabled %}
    {% for test in node.tests %}
        {% if test.runOrder == 'After' %}
            {{ test_stage(test.name, test.continueOnFailure) }}
            {{ test.templateString }}
        {% endif %}
    {% endfor %}

    {% for column in columns %}
        {% for test in column.tests %}
            {{ test_stage(column.name + ": " + test.name) }}
            {{ test.templateString }}
        {% endfor %}
    {% endfor %}
{% endif %}

